    ('UM_BACHELOR_077', 'Semester 1 (October) Intake', 'https://study.um.edu.my/bachelor-of-sports-management', '2026-10-14T05:47:17.864Z'),
    ('UM_BACHELOR_077', 'Semester 2 (March) Intake', 'https://study.um.edu.my/bachelor-of-sports-management', '2026-10-14T05:47:17.864Z'),
    ('UM_BACHELOR_078', 'Semester 1 (October) Intake', 'https://study.um.edu.my/bachelor-of-sport-sciences', '2026-10-14T05:47:19.876Z'),
    ('UM_BACHELOR_078', 'Semester 2 (March) Intake', 'https://study.um.edu.my/bachelor-of-sport-sciences', '2026-10-14T05:47:19.876Z');
DO $$ BEGIN
  IF (SELECT COUNT(*) FROM official_um_programme_updates) <> 72 THEN
    RAISE EXCEPTION 'Unexpected official UM basic-information update count';
  END IF;
END $$;

UPDATE programmes p SET
  duration_months = f.duration_months,
  duration_display = CONCAT(f.duration_months, '个月；全日制（授课型）'),
  study_pace_display = '全日制（授课型）',
  tuition_min = f.tuition_min,
  tuition_max = f.tuition_max,
  tuition_currency = f.tuition_currency,
  tuition_display = CONCAT(f.tuition_currency, ' ', TO_CHAR(f.tuition_min, 'FM999,999,999,990.00'), '（国际学生；计费周期以官网为准）'),
  tuition_fee_period = 'UNKNOWN',
  official_url = f.official_url,
  source_checked_at = f.source_checked_at,
  updated_at = CURRENT_TIMESTAMP
FROM official_um_programme_updates f, universities u
WHERE p.programme_code = f.programme_code
  AND p.university_id = u.id
  AND u.slug = 'um'
  AND p.status = 'PUBLISHED';

-- Replace only the known legacy month-only labels on the same programme. No row
-- is deleted; all source-backed intake rows absent from the catalogue are added.
UPDATE programme_intakes pi SET
  display_text = CASE
    WHEN pi.display_text IN ('9月', 'September', 'September Intake') THEN '10月（第一学期）'
    WHEN pi.display_text IN ('3月', 'March', 'March Intake') THEN '3月（第二学期）'
    ELSE pi.display_tex
  END,
  source_url = f.source_url,
  source_checked_at = f.source_checked_a
FROM programmes p
JOIN universities u ON u.id = p.university_id
JOIN official_um_programme_updates f ON f.programme_code = p.programme_code
WHERE pi.programme_id = p.id
  AND u.slug = 'um'
  AND p.status = 'PUBLISHED'
  AND pi.display_text IN ('9月', 'September', 'September Intake', '3月', 'March', 'March Intake');

INSERT INTO programme_intakes (programme_id, intake_date, display_text, source_url, source_checked_at, created_at)
SELECT p.id, NULL,
  CASE
    WHEN i.display_text LIKE '%October%' THEN '10月（第一学期）'
    WHEN i.display_text LIKE '%March%' THEN '3月（第二学期）'
    ELSE i.display_tex
  END,
  i.source_url, i.source_checked_at, CURRENT_TIMESTAMP
FROM official_um_programme_intakes i
JOIN programmes p ON p.programme_code = i.programme_code
JOIN universities u ON u.id = p.university_id
WHERE u.slug = 'um'
  AND p.status = 'PUBLISHED'
  AND NOT EXISTS (
    SELECT 1 FROM programme_intakes existing
    WHERE existing.programme_id = p.id
      AND existing.display_text = CASE
        WHEN i.display_text LIKE '%October%' THEN '10月（第一学期）'
        WHEN i.display_text LIKE '%March%' THEN '3月（第二学期）'
        ELSE i.display_tex
      END
  );

UPDATE programme_detail_sections s SET
  title_zh = '入学要求',
  updated_at = CURRENT_TIMESTAMP
FROM programmes p
JOIN universities u ON u.id = p.university_id
JOIN official_um_programme_updates f ON f.programme_code = p.programme_code
WHERE s.programme_id = p.id
  AND s.section_type = 'ADMISSIONS'
  AND u.slug = 'um'
  AND p.status = 'PUBLISHED'
  AND s.source_url = f.official_url
  AND NULLIF(BTRIM(s.title_zh), '') IS NULL;

INSERT INTO search_sync_jobs (university_id, status, attempt_count, available_at, created_at, updated_at)
SELECT u.id, 'PENDING', 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM universities u
WHERE u.slug = 'um'
  AND u.status = 'PUBLISHED'
  AND NOT EXISTS (
    SELECT 1 FROM search_sync_jobs j
    WHERE j.university_id = u.id AND j.status = 'PENDING'
  );
